import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { createMessage, getInboxMessages, getSentMessages, markMessageAsRead, toggleMessageStar } from '../services/api';
import './Messages.css';

const emptyForm = { recipientEmail: '', subject: '', body: '' };

export default function Messages() {
  const [activeTab, setActiveTab] = useState('inbox');
  const [messages, setMessages] = useState([]);
  const [selectedId, setSelectedId] = useState(null);
  const [search, setSearch] = useState('');
  const [showComposer, setShowComposer] = useState(false);
  const [form, setForm] = useState(emptyForm);
  const [selectedIds, setSelectedIds] = useState([]);
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState({ type: '', text: '' });

  const fetchMessages = useCallback(async () => {
    setLoading(true);
    try {
      const response = activeTab === 'sent' ? await getSentMessages() : await getInboxMessages();
      const data = Array.isArray(response.data) ? response.data : [];
      setMessages(data);
      setSelectedIds([]);
      if (data.length > 0) {
        setSelectedId((current) => current && data.some((item) => item.id === current) ? current : data[0].id);
      } else {
        setSelectedId(null);
      }
      setStatusMessage({ type: '', text: '' });
    } catch (error) {
      console.error('Error cargando mensajes:', error.response?.data || error.message);
      setStatusMessage({ type: 'error', text: error.response?.data?.mensaje || 'No se pudieron cargar los mensajes.' });
    } finally {
      setLoading(false);
    }
  }, [activeTab]);

  useEffect(() => {
    fetchMessages();
  }, [fetchMessages]);

  const filteredMessages = useMemo(() => {
    const query = search.toLowerCase().trim();
    let result = messages;

    if (activeTab === 'starred') {
      result = result.filter((message) => message.isStarred);
    }

    if (!query) return result;

    return result.filter((message) => {
      const haystack = [message.subject, message.body, message.senderName, message.senderEmail, message.recipientEmail]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();

      return haystack.includes(query);
    });
  }, [messages, search, activeTab]);

  const selectedMessage = filteredMessages.find((message) => message.id === selectedId) || filteredMessages[0] || null;

  const openMessage = async (message) => {
    setSelectedId(message.id);

    if (activeTab === 'inbox' && !message.isRead) {
      try {
        await markMessageAsRead(message.id);
        setMessages((current) => current.map((item) => item.id === message.id ? { ...item, isRead: true } : item));
      } catch (error) {
        console.error('Error marcando mensaje:', error.response?.data || error.message);
      }
    }
  };

  const handleToggleStar = async (message) => {
    try {
      const nextValue = !message.isStarred;
      await toggleMessageStar(message.id, nextValue);
      setMessages((current) => current.map((item) => item.id === message.id ? { ...item, isStarred: nextValue } : item));
    } catch (error) {
      console.error('Error actualizando destacado:', error.response?.data || error.message);
      setStatusMessage({ type: 'error', text: 'No se pudo actualizar el destacado del mensaje.' });
    }
  };

  const toggleSelection = (messageId) => {
    setSelectedIds((current) => current.includes(messageId)
      ? current.filter((id) => id !== messageId)
      : [...current, messageId]);
  };

  const handleSend = async (e) => {
    e.preventDefault();

    if (!form.recipientEmail || !form.subject || !form.body) {
      setStatusMessage({ type: 'error', text: 'Completa destinatario, asunto y mensaje.' });
      return;
    }

    try {
      const created = await createMessage(form);
      setMessages((current) => [created.data, ...current]);
      setForm(emptyForm);
      setShowComposer(false);
      setActiveTab('sent');
      setSelectedId(created.data.id);
      setStatusMessage({ type: 'success', text: 'Mensaje enviado correctamente.' });
    } catch (error) {
      console.error('Error enviando mensaje:', error.response?.data || error.message);
      setStatusMessage({ type: 'error', text: error.response?.data?.mensaje || 'No se pudo enviar el mensaje.' });
    }
  };

  return (
    <div className="messages-page">
      <div className="messages-header">
        <div>
          <p className="messages-eyebrow">Centro de comunicaciones</p>
          <h2>📨 Mensajería</h2>
        </div>
        <div className="messages-search-wrap">
          <input
            className="messages-search"
            type="text"
            placeholder="Buscar en mensajes"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <button className="btn-primary" onClick={() => setShowComposer(true)}>+ Redactar</button>
        </div>
      </div>

      {statusMessage.text && <div className={`status-message ${statusMessage.type}`}>{statusMessage.text}</div>}

      <div className="messages-layout">
        <aside className="messages-sidebar">
          <div className="sidebar-card">
            <button className="compose-button" onClick={() => setShowComposer(true)}>✉️ Redactar</button>
            <div className="folder-list">
              {[
                { key: 'inbox', label: 'Recibidos' },
                { key: 'starred', label: 'Destacados' },
                { key: 'sent', label: 'Enviados' }
              ].map((folder) => {
                const isActive = activeTab === folder.key;
                return (
                  <button
                    key={folder.key}
                    className={`folder-item ${isActive ? 'active' : ''}`}
                    onClick={() => setActiveTab(folder.key)}
                  >
                    {folder.label}
                  </button>
                );
              })}
            </div>
          </div>
        </aside>

        <section className="messages-list-panel">
          <div className="list-header">
            <div>
              <h3>{activeTab === 'sent' ? 'Enviados' : activeTab === 'starred' ? 'Destacados' : 'Recibidos'}</h3>
              <p>{filteredMessages.length} mensajes</p>
            </div>
            <span className="selection-pill">{selectedIds.length} seleccionados</span>
          </div>

          {loading ? (
            <div className="empty-state">Cargando mensajes...</div>
          ) : filteredMessages.length === 0 ? (
            <div className="empty-state">No hay mensajes para mostrar.</div>
          ) : (
            <div className="message-list">
              {filteredMessages.map((message) => (
                <article
                  key={message.id}
                  className={`message-row ${message.isRead ? '' : 'unread'} ${selectedMessage?.id === message.id ? 'selected' : ''}`}
                >
                  <input
                    type="checkbox"
                    checked={selectedIds.includes(message.id)}
                    onChange={() => toggleSelection(message.id)}
                    onClick={(e) => e.stopPropagation()}
                  />
                  <button
                    className={`star-button ${message.isStarred ? 'active' : ''}`}
                    onClick={(e) => {
                      e.stopPropagation();
                      handleToggleStar(message);
                    }}
                  >
                    ★
                  </button>
                  <div className="message-column sender" onClick={() => openMessage(message)}>
                    <strong>{activeTab === 'sent' ? message.recipientEmail : message.senderName}</strong>
                  </div>
                  <div className="message-column content" onClick={() => openMessage(message)}>
                    <div className="message-subject">{message.subject}</div>
                    <div className="message-snippet">{message.snippet || message.body}</div>
                  </div>
                  <div className="message-column time" onClick={() => openMessage(message)}>
                    {new Date(message.createdAt).toLocaleTimeString('es-CL', { hour: '2-digit', minute: '2-digit' })}
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>

        <section className="messages-detail-panel">
          {selectedMessage ? (
            <article className="detail-card">
              <div className="detail-top">
                <div>
                  <p className="detail-label">{activeTab === 'sent' ? 'Para' : 'De'}</p>
                  <h3>{activeTab === 'sent' ? selectedMessage.recipientEmail : selectedMessage.senderName}</h3>
                  <p className="detail-meta">{activeTab === 'sent' ? selectedMessage.recipientEmail : selectedMessage.senderEmail}</p>
                </div>
                <div className="detail-actions">
                  <button className={`star-button ${selectedMessage.isStarred ? 'active' : ''}`} onClick={() => handleToggleStar(selectedMessage)}>★</button>
                </div>
              </div>

              <div className="detail-body">
                <p className="detail-subject">{selectedMessage.subject}</p>
                <p className="detail-time">{new Date(selectedMessage.createdAt).toLocaleString('es-CL')}</p>
                <div className="detail-message">{selectedMessage.body}</div>
              </div>
            </article>
          ) : (
            <div className="empty-state">Selecciona un mensaje para ver su detalle.</div>
          )}
        </section>
      </div>

      {showComposer && (
        <div className="composer-overlay" onClick={() => setShowComposer(false)}>
          <div className="composer-modal" onClick={(e) => e.stopPropagation()}>
            <div className="composer-header">
              <div>
                <h3>Nuevo mensaje</h3>
                <p>Escribe tu mensaje y envíalo al destinatario.</p>
              </div>
              <button className="close-button" onClick={() => setShowComposer(false)}>×</button>
            </div>

            <form className="composer-form" onSubmit={handleSend}>
              <label>
                Destinatario
                <input
                  type="email"
                  value={form.recipientEmail}
                  onChange={(e) => setForm({ ...form, recipientEmail: e.target.value })}
                  placeholder="correo@empresa.cl"
                  required
                />
              </label>

              <label>
                Asunto
                <input
                  type="text"
                  value={form.subject}
                  onChange={(e) => setForm({ ...form, subject: e.target.value })}
                  placeholder="Asunto del mensaje"
                  required
                />
              </label>

              <label>
                Mensaje
                <textarea
                  rows="8"
                  value={form.body}
                  onChange={(e) => setForm({ ...form, body: e.target.value })}
                  placeholder="Escribe tu mensaje..."
                  required
                />
              </label>

              <div className="composer-actions">
                <button type="button" className="btn-secondary" onClick={() => setShowComposer(false)}>Cancelar</button>
                <button type="submit" className="btn-primary">Enviar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
